SELECT [TB Time Keeping].[Bill Sent], [TB Time Keeping].[Bill Paid], [TB Time Keeping].[Bill Closed], [TB Time Keeping].[BilL Closed Date], [TB Time Keeping].Discount, [TB Time Keeping].IANumber, Replace([Case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty],"__","_") AS FileNumber, [SumOfAmount]-Nz([Discount]) AS BalanceCalculated, tblCase.*, [TB Time Keeping].[Bill Open], [tblCase].[Last_Name] & ", " & [tblCase].[First_Name] AS Name, [TB Time Keeping].Bill_ID, [TB Time Keeping].TrustatClose, [TB Time Keeping].StatementLessTrust, [TB Time Keeping].InvoiceExceedsTrust, [TB Time Keeping].InvoiceTotalAdvance, [TB Time Keeping].Bill_ID, [TB Time Keeping].InvoiceNoAdvance
FROM tblCase INNER JOIN ([TB Time Keeping] INNER JOIN qry_time_table_totals ON [TB Time Keeping].Bill_ID = qry_time_table_totals.Bill_ID) ON tblCase.CaseID = [TB Time Keeping].CaseID
WHERE ((([TB Time Keeping].[Bill Closed])=Yes) AND (([TB Time Keeping].[BilL Closed Date]) Between Date() And Date()-30));